    exec(compileCommand, (error, stdout, stderr) => {
      // Clean up the temporary file
      fs.unlinkSync(tempFilePath);

      if (error) {
        return resolve({ hasError: true, compilerError: stderr.trim() });
      }
      return resolve({ hasError: false, compilerError: null });
    });
  }).then((result) => {
    reply.send(result);
  });
});

